#include <bits/stdc++.h>
#define rep(i,n) for (int i=0; i<(n); i++)
using namespace std;
typedef long long ll;
typedef pair<int,int> pii;

struct Edge { int to, capacity, cost, rev; };

struct CostFlow {
    static const int MAXV = 5010;
    int V;
    vector<Edge> graph[MAXV];
    int potential[MAXV], dist[MAXV], prevVertex[MAXV], prevEdge[MAXV];

    void init(int n) {
        V = n;
        for (int i=0; i<V; i++) graph[i].clear();
    }

    void addEdge(int from, int to, int cap, int cst) {
        graph[from].push_back({to, cap, cst, (int)graph[to].size()});
        graph[to].push_back({from, 0, -cst, (int)graph[from].size() - 1});
    }

    int minCostFlow(int s, int t, int flow) {
        int res = 0;
        fill(potential, potential+V, 0);
        while (flow > 0) {
            priority_queue<pii, vector<pii>, greater<pii>> pq;
            fill(dist, dist+V, INT_MAX);
            dist[s] = 0;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (dist[v] < d) continue;
                for (int i=0; i<(int)graph[v].size(); i++) {
                    Edge &e = graph[v][i];
                    if (e.capacity > 0 && dist[e.to] > dist[v] + e.cost + potential[v] - potential[e.to]) {
                        dist[e.to] = dist[v] + e.cost + potential[v] - potential[e.to];
                        prevVertex[e.to] = v;
                        prevEdge[e.to] = i;
                        pq.push({dist[e.to], e.to});
                    }
                }
            }
            if (dist[t] == INT_MAX) return -1;
            for (int v=0; v<V; v++) potential[v] += dist[v];
            int addFlow = flow;
            for (int v=t; v!=s; v=prevVertex[v]) {
                addFlow = min(addFlow, graph[prevVertex[v]][prevEdge[v]].capacity);
            }
            flow -= addFlow;
            res += addFlow * potential[t];
            for (int v=t; v!=s; v=prevVertex[v]) {
                Edge &e = graph[prevVertex[v]][prevEdge[v]];
                e.capacity -= addFlow;
                graph[v][e.rev].capacity += addFlow;
            }
        }
        return res;
    }
};

CostFlow flowSolver;

int n, m, k, c, d;
int a[50];
int countArr[50];
vector<int> adj[50];

const int T = 100;

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    rep(i,k) scanf("%d", a+i);
    rep(i,k) countArr[a[i]-1]++;
    rep(i,m) {
        int x, y; scanf("%d%d", &x, &y);
        x--; y--;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    flowSolver.init(n*T+2);
    rep(i,n) flowSolver.addEdge(n*T, i, countArr[i], 0);
    rep(i,T) flowSolver.addEdge(i*n, n*T+1, k, c*i);
    rep(i,n) {
        rep(j,T-1) flowSolver.addEdge(j*n+i, (j+1)*n+i, k, 0);
        for (int to: adj[i]) {
            rep(j,T-1) {
                rep(u,k) {
                    int cost = (u+1)*(u+1)*d - u*u*d;
                    flowSolver.addEdge(j*n+i, (j+1)*n+to, 1, cost);
                }
            }
        }
    }
    printf("%d\n", flowSolver.minCostFlow(n*T, n*T+1, k));
}
